window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-61fc40b0108b7791"]={"versions": [{"id": "FIG-61fc40b0108b7791", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Spezifikation von Kommunikationsbeziehungen im System Template von AUTOSAR Classic Platform. Das Diagramm visualisiert die Konfigurationsmuster und die Ableitung von ECU-Parametern im Socket Adapter (SoAd) für Unicast-Kommunikationsszenarien zwischen einem Server und zwei Clients.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende UML-Objektinstanzen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:SocketConnectionBundle</code>: Bündelungsentität, die über Kompositionsbeziehungen zwei Verbindungen aggregiert und auf die Serveradresse verweist (<code>ServerAddress : SocketAddress</code>).</li>\n<li><code>ServerAddress : SocketAddress</code>: Spezifiziert die Server-Endpunktadresse mit Port 80 und IP-Adresse 192.168.1.1.</li>\n<li><code>Client1Connection :SocketConnection</code>: Verbindungsausprägung für Szenario 3 mit den Attributwerten:</li>\n<li><code>clientIpAddrFromConnectionRequest = true</code></li>\n<li><code>clientPortFromConnectionRequest = true</code></li>\n<li><code>runtimeIpAddressConfiguration = none</code></li>\n<li><code>runtimePortConfiguration = none</code></li>\n</ul>\n<p class=\"fig-p\">Sie referenziert über eine gerichtete Assoziation <code>Client1Address : SocketAddress</code>.</p>\n<ul class=\"fig-list\">\n<li><code>Client1Address : SocketAddress</code>: Client-Adresse für Szenario 3 mit Port 8001 und IP-Adresse 192.168.1.100.</li>\n<li><code>Client2Connection :SocketConnection</code>: Verbindungsausprägung für Szenario 4 mit den Attributwerten:</li>\n<li><code>clientIpAddrFromConnectionRequest = false</code></li>\n<li><code>clientPortFromConnectionRequest = false</code></li>\n<li><code>runtimeIpAddressConfiguration = sd</code></li>\n<li><code>runtimePortConfiguration = sd</code></li>\n</ul>\n<p class=\"fig-p\">Sie referenziert über eine gerichtete Assoziation <code>Client2Address : SocketAddress</code>.</p>\n<ul class=\"fig-list\">\n<li><code>Client2Address : SocketAddress</code>: Client-Adresse für Szenario 4 mit Port 8002 und IP-Adresse 192.168.1.101.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei unterschiedliche Unicast-Szenarien gegenüber:</p>\n<ul class=\"fig-list\">\n<li>Szenario 3 (dynamische Client-Ermittlung am Server beim Verbindungsaufbau): Der Server ermittelt IP-Adresse und Port des Clients dynamisch beim Eintreffen des Verbindungsantrags (<code>clientIpAddrFromConnectionRequest = true</code>, <code>clientPortFromConnectionRequest = true</code>). Der Client konfiguriert Server-IP und Port statisch zur Konfigurationszeit (<code>runtimeIpAddressConfiguration = none</code>, <code>runtimePortConfiguration = none</code>).</li>\n<li>Szenario 4 (statischer Client am Server, dynamische Server-Ermittlung via Service Discovery): Der Server kennt Client-IP und Port fest zur Konfigurationszeit (<code>clientIpAddrFromConnectionRequest = false</code>, <code>clientPortFromConnectionRequest = false</code>). Der Client ermittelt Server-IP und Port zur Laufzeit über den Service-Discovery-Dienst (<code>runtimeIpAddressConfiguration = sd</code>, <code>runtimePortConfiguration = sd</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Abbildung von System-Template-Parametern auf die SoAd-Modulkonfiguration der ECUs:</p>\n<ul class=\"fig-list\">\n<li>Szenario 3 führt zu:</li>\n<li>Server: <code>SoAdSocketRemoteIpAddress: ANY</code>, <code>SoAdSocketRemotePort: 0</code> (akzeptiert Verbindungen beliebiger Clients).</li>\n<li>Client1: <code>SoAdSocketRemoteIpAddress: 192.168.1.1</code>, <code>SoAdSocketRemotePort: 80</code>.</li>\n<li>Szenario 4 führt zu:</li>\n<li>Server: <code>SoAdSocketRemoteIpAddress: 192.168.1.101</code>, <code>SoAdSocketRemotePort: 8002</code> (feste Zuordnung auf den spezifischen Client-Endpunkt).</li>\n<li>Client2: <code>SoAdSocketRemoteIpAddress: ANY</code>, <code>SoAdSocketRemotePort: 0</code> (Platzhalterkonfiguration bis zur Auflösung durch SD).</li>\n</ul>"}, {"id": "FIG-8063bd7c2774dedf", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Spezifikation von Kommunikationsbeziehungen im System Template von AUTOSAR Classic Platform. Das Diagramm visualisiert die Konfigurationsmuster und die Ableitung von ECU-Parametern im Socket Adapter (SoAd) für Unicast-Kommunikationsszenarien zwischen einem Server und zwei Clients.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende UML-Objektinstanzen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:SocketConnectionBundle</code>: Bündelungsentität, die über Kompositionsbeziehungen zwei Verbindungen aggregiert und auf die Serveradresse verweist (<code>ServerAddress : SocketAddress</code>).</li>\n<li><code>ServerAddress : SocketAddress</code>: Spezifiziert die Server-Endpunktadresse mit Port 80 und IP-Adresse 192.168.1.1.</li>\n<li><code>Client1Connection :SocketConnection</code>: Verbindungsausprägung für Szenario 3 mit den Attributwerten:</li>\n<li><code>clientIpAddrFromConnectionRequest = true</code></li>\n<li><code>clientPortFromConnectionRequest = true</code></li>\n<li><code>runtimeIpAddressConfiguration = none</code></li>\n<li><code>runtimePortConfiguration = none</code></li>\n</ul>\n<p class=\"fig-p\">Sie referenziert über eine gerichtete Assoziation <code>Client1Address : SocketAddress</code>.</p>\n<ul class=\"fig-list\">\n<li><code>Client1Address : SocketAddress</code>: Client-Adresse für Szenario 3 mit Port 8001 und IP-Adresse 192.168.1.100.</li>\n<li><code>Client2Connection :SocketConnection</code>: Verbindungsausprägung für Szenario 4 mit den Attributwerten:</li>\n<li><code>clientIpAddrFromConnectionRequest = false</code></li>\n<li><code>clientPortFromConnectionRequest = false</code></li>\n<li><code>runtimeIpAddressConfiguration = sd</code></li>\n<li><code>runtimePortConfiguration = sd</code></li>\n</ul>\n<p class=\"fig-p\">Sie referenziert über eine gerichtete Assoziation <code>Client2Address : SocketAddress</code>.</p>\n<ul class=\"fig-list\">\n<li><code>Client2Address : SocketAddress</code>: Client-Adresse für Szenario 4 mit Port 8002 und IP-Adresse 192.168.1.101.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei unterschiedliche Unicast-Szenarien gegenüber:</p>\n<ul class=\"fig-list\">\n<li>Szenario 3 (dynamische Client-Ermittlung am Server beim Verbindungsaufbau): Der Server ermittelt IP-Adresse und Port des Clients dynamisch beim Eintreffen des Verbindungsantrags (<code>clientIpAddrFromConnectionRequest = true</code>, <code>clientPortFromConnectionRequest = true</code>). Der Client konfiguriert Server-IP und Port statisch zur Konfigurationszeit (<code>runtimeIpAddressConfiguration = none</code>, <code>runtimePortConfiguration = none</code>).</li>\n<li>Szenario 4 (statischer Client am Server, dynamische Server-Ermittlung via Service Discovery): Der Server kennt Client-IP und Port fest zur Konfigurationszeit (<code>clientIpAddrFromConnectionRequest = false</code>, <code>clientPortFromConnectionRequest = false</code>). Der Client ermittelt Server-IP und Port zur Laufzeit über den Service-Discovery-Dienst (<code>runtimeIpAddressConfiguration = sd</code>, <code>runtimePortConfiguration = sd</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Abbildung von System-Template-Parametern auf die SoAd-Modulkonfiguration der ECUs:</p>\n<ul class=\"fig-list\">\n<li>Szenario 3 führt zu:</li>\n<li>Server: <code>SoAdSocketRemoteIpAddress: ANY</code>, <code>SoAdSocketRemotePort: 0</code> (akzeptiert Verbindungen beliebiger Clients).</li>\n<li>Client1: <code>SoAdSocketRemoteIpAddress: 192.168.1.1</code>, <code>SoAdSocketRemotePort: 80</code>.</li>\n<li>Szenario 4 führt zu:</li>\n<li>Server: <code>SoAdSocketRemoteIpAddress: 192.168.1.101</code>, <code>SoAdSocketRemotePort: 8002</code> (feste Zuordnung auf den spezifischen Client-Endpunkt).</li>\n<li>Client2: <code>SoAdSocketRemoteIpAddress: ANY</code>, <code>SoAdSocketRemotePort: 0</code> (Platzhalterkonfiguration bis zur Auflösung durch SD).</li>\n</ul>"}, {"id": "FIG-8393f937fb601d90", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Spezifikation von Kommunikationsbeziehungen im System Template von AUTOSAR Classic Platform. Das Diagramm visualisiert die Konfigurationsmuster und die Ableitung von ECU-Parametern im Socket Adapter (SoAd) für Unicast-Kommunikationsszenarien zwischen einem Server und zwei Clients.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende UML-Objektinstanzen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:SocketConnectionBundle</code>: Bündelungsentität, die über Kompositionsbeziehungen zwei Verbindungen aggregiert und auf die Serveradresse verweist (<code>ServerAddress: SocketAddress</code>).</li>\n<li><code>ServerAddress: SocketAddress</code>: Spezifiziert die Server-Endpunktadresse mit Port 80 und IP-Adresse 192.168.1.1.</li>\n<li><code>Client1Connection: SocketConnection</code>: Verbindungsausprägung für Szenario 3 mit den Attributwerten:</li>\n<li><code>clientIpAddrFromConnectionRequest = true</code></li>\n<li><code>clientPortFromConnectionRequest = true</code></li>\n<li><code>runtimeIpAddressConfiguration = none</code></li>\n<li><code>runtimePortConfiguration = none</code></li>\n</ul>\n<p class=\"fig-p\">Sie referenziert über eine gerichtete Assoziation <code>Client1Address: SocketAddress</code>.</p>\n<ul class=\"fig-list\">\n<li><code>Client1Address: SocketAddress</code>: Client-Adresse für Szenario 3 mit Port 8001 und IP-Adresse 192.168.1.100.</li>\n<li><code>Client2Connection: SocketConnection</code>: Verbindungsausprägung für Szenario 4 mit den Attributwerten:</li>\n<li><code>clientIpAddrFromConnectionRequest = false</code></li>\n<li><code>clientPortFromConnectionRequest = false</code></li>\n<li><code>runtimeIpAddressConfiguration = sd</code></li>\n<li><code>runtimePortConfiguration = sd</code></li>\n</ul>\n<p class=\"fig-p\">Sie referenziert über eine gerichtete Assoziation <code>Client2Address: SocketAddress</code>.</p>\n<ul class=\"fig-list\">\n<li><code>Client2Address: SocketAddress</code>: Client-Adresse für Szenario 4 mit Port 8002 und IP-Adresse 192.168.1.101.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei unterschiedliche Unicast-Szenarien gegenüber:</p>\n<ul class=\"fig-list\">\n<li>Szenario 3 (dynamische Client-Ermittlung am Server beim Verbindungsaufbau): Der Server ermittelt IP-Adresse und Port des Clients dynamisch beim Eintreffen des Verbindungsantrags (<code>clientIpAddrFromConnectionRequest = true</code>, <code>clientPortFromConnectionRequest = true</code>). Der Client konfiguriert Server-IP und Port statisch zur Konfigurationszeit (<code>runtimeIpAddressConfiguration = none</code>, <code>runtimePortConfiguration = none</code>).</li>\n<li>Szenario 4 (statischer Client am Server, dynamische Server-Ermittlung via Service Discovery): Der Server kennt Client-IP und Port fest zur Konfigurationszeit (<code>clientIpAddrFromConnectionRequest = false</code>, <code>clientPortFromConnectionRequest = false</code>). Der Client ermittelt Server-IP und Port zur Laufzeit über den Service-Discovery-Dienst (<code>runtimeIpAddressConfiguration = sd</code>, <code>runtimePortConfiguration = sd</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Abbildung von System-Template-Parametern auf die SoAd-Modulkonfiguration der ECUs:</p>\n<ul class=\"fig-list\">\n<li>Szenario 3 führt zu:</li>\n<li>Server: <code>SoAdSocketRemoteIpAddress: ANY</code>, <code>SoAdSocketRemotePort: 0</code> (akzeptiert Verbindungen beliebiger Clients).</li>\n<li>Client1: <code>SoAdSocketRemoteIpAddress: 192.168.1.1</code>, <code>SoAdSocketRemotePort: 80</code>.</li>\n<li>Szenario 4 führt zu:</li>\n<li>Server: <code>SoAdSocketRemoteIpAddress: 192.168.1.101</code>, <code>SoAdSocketRemotePort: 8002</code> (feste Zuordnung auf den spezifischen Client-Endpunkt).</li>\n<li>Client2: <code>SoAdSocketRemoteIpAddress: ANY</code>, <code>SoAdSocketRemotePort: 0</code> (Platzhalterkonfiguration bis zur Auflösung durch SD).</li>\n</ul>"}], "trans": [{"from": "FIG-61fc40b0108b7791", "to": "FIG-8063bd7c2774dedf", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8063bd7c2774dedf", "to": "FIG-8393f937fb601d90", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Typografische Vereinheitlichung der UML-Objektbezeichner: Leerzeichen vor dem Doppelpunkt entfernt in <code>ServerAddress: SocketAddress</code>, <code>Client1Address: SocketAddress</code>, <code>Client2Address: SocketAddress</code>, <code>Client1Connection: SocketConnection</code> und <code>Client2Connection: SocketConnection</code> (zuvor jeweils Leerzeichen vor <code>:</code>).</li>\n</ul>"}]};
